        { pattern = "^i need (.+)$", rule = "r_want" },
        { pattern = "^i think (.+)$", rule = "r_think" },
        { pattern = "^i (.+)$", rule = "r_i" },
        { pattern = "^my (.+)$", rule = "r_my" },
