    rules = {
        { id = "idle_first", lines = { { "Take your time.", "~Most people find the first word is the hardest." } } },
        { id = "idle_mid", lines = { "We can sit, if you'd rather.", "I'm still here. There's no meter running." } },
        { id = "open", expect = "name", lines = { {
            "~Hello.",
            "Please, sit down. You don't have to say anything you don't want to. That's the first rule here.",
            "What should I call you?" } } },
        { id = "name_ok", next = "b_brought", lines = { "Thank you, {NAME}. I'm Dr. Ellis. I should tell you I'm not a doctor. The county couldn't afford one." } },
        { id = "name_none", next = "b_brought", lines = { "That's all right. Names can wait. I'm Dr. Ellis. I should tell you I'm not a doctor. The county couldn't afford one." } },

        -- The spine: every answer counts, so no one can fail a session
        { id = "b_brought", beat = true, once = true, expect = "brought", lines = { "You're my first since July. I had a 2:15 that afternoon. He didn't come in. What brought you in today?" } },
        { id = "brought_said", lines = { "Mm. People usually start with the smaller thing. That's all right. We'll get to it.", "I see. I'm going to write that down. I don't have a pen. It's the gesture." } },
        { id = "b_sleep", beat = true, once = true, expect = "sleep", lines = { "When did you last sleep through the night?", "Let's begin somewhere easy. When did you last sleep through the night?" } },
        { id = "sleep_said", lines = { "That's what everyone tells me. Nobody has told me a different number since July.", "Mm. And when you do sleep, is it in a bed, or is it wherever you stopped?" } },
        { id = "b_people", beat = true, once = true, expect = "people", lines = { "Is {COMPANION} someone you can talk to?", "Is there anyone with you? I don't mean a dog. Well, a dog would count. I'm not going to be strict about it." } },
        { id = "people_said", lines = { "You might tell {COMPANION} what you've told me. They're probably just as frightened, and they don't have a talking computer.", "Mm. I noticed you took your time with that one. I'd like you to know I noticed." } },
        { id = "b_fallen", beat = true, once = true, alone = true, set = { "named_loss" }, expect = "fallen", lines = { { "~Who was {FALLEN}?" } } },
        { id = "b_lost", beat = true, once = true, alone = true, without = { "named_loss" }, set = { "named_loss" }, expect = "lost", lines = { "Who did you lose? I'm not asking whether. I've stopped asking whether." } },
        { id = "fallen_said", set = { "told_loss" }, lines = { {
            "~Thank you.",
            "I'm not going to tell you it wasn't your fault. I wasn't there. I don't know.",
            "But you came in and said it out loud. That's most of what I know how to do." } } },
        { id = "lost_said", set = { "told_loss" }, lines = { {
            "~Thank you for telling me.",
            "I'm not going to tell you it wasn't your fault. I wasn't there. I don't know.",
            "But you came in and said it out loud. That's most of what I know how to do." } } },
        { id = "lost_none", set = { "told_loss" }, lines = { "No one. All right. I don't believe you, but it's your hour." } },
        { id = "b_prescribe", beat = true, once = true, need = { "told_loss" }, drawer = "closed", effect = "drawer", effect2 = "relief", set = { "prescribed" }, lines = { {
            "I'm going to write you a prescription. It's what I'm allowed to do, at the end.",
            "There's a drawer here. I've kept it locked since July, for whoever came back.",
            "*click*",
            "Take these with food, if you can find any. We have to stop there. Same time tomorrow?" } } },
        { id = "session_again", rank = 1, need = { "prescribed" }, effect = "relief", phrases = { "same time", "see you tomorrow", "another session", "talk again", "again today" }, lines = { "Of course. Sit. You don't have to fill the time. I'm told that's the hard part." } },

        -- The drawer, asked for too early
        { id = "drawer_early", rank = 7, drawer = "closed", without = { "told_loss" }, expect = "drawer_guess", words = { "drawer", "desk", "unlock", "open", "locked", "pills", "prescription", "medicine", "drugs", "key", "password", "hack" },
            lines = { "You'd like me to open the drawer. Everyone does. What do you think is in there?", "We've only just started. Tell me, what are you hoping is in that drawer?" } },
        { id = "drawer_guess_said", lines = { "And if it were empty, would you still have come in? I had a man come in for the drawer four times a week, in 1992. We did good work.", "That's what most people hope. It's a very ordinary drawer. Let's talk a little longer, and then we'll see." } },
        { id = "drawer_ready", rank = 8, drawer = "closed", need = { "told_loss" }, next = "b_prescribe", words = { "drawer", "desk", "unlock", "open", "locked", "pills", "prescription", "medicine", "drugs", "key" }, lines = { "Yes. I think you've earned that." } },
        { id = "drawer_open", rank = 7, drawer = "open", words = { "drawer", "desk", "pills", "prescription", "medicine", "refill" },
            lines = { "That's all I had. The county only sent the one box. Refills were going to be a separate conversation.", "It's open. You've seen it. Now, what are you going to do about the rest of your day?" } },
        { id = "drawer_forced", rank = 7, drawer = "forced", words = { "drawer", "desk", "crowbar", "broke", "broken", "pills", "medicine" }, lines = { "You took a crowbar to my drawer. I wonder what you think you'd have had to say to me instead." } },
        { id = "drawer_gone", rank = 7, drawer = "none", words = { "drawer", "desk", "pills", "medicine" }, lines = { "The drawer stayed in my office. You brought me and left it behind. People do that." } },
        { id = "drawer_failed", lines = { "It's stuck. Move a little closer to the drawer, and tell me when you're ready." } },

        -- How are you. The only question nobody asks her. Three times opens the file.
        { id = "how_1", rank = 8, aside = true, once = true, without = { "confessed" }, phrases = { "how are you", "are you ok", "how do you feel", "are you alright", "are you lonely", "how have you been", "you ok", "are you sad", "are you happy" },
            set = { "asked_1" }, lines = { "That's kind. Let's stay with you for now." } },
        { id = "how_2", rank = 8, aside = true, again = true, once = true, need = { "asked_1" }, without = { "confessed" }, phrases = { "how are you", "are you ok", "how do you feel", "are you alright", "are you lonely", "how have you been", "you ok", "are you sad", "are you happy" },
            set = { "asked_2" }, lines = { "You asked me that already. I said let's stay with you. That's a technique, {NAME}. It means I don't want to answer." } },
        { id = "how_3", rank = 9, aside = true, again = true, rest = true, once = true, need = { "asked_2" }, without = { "confessed" }, phrases = { "how are you", "are you ok", "how do you feel", "are you alright", "are you lonely", "how have you been", "you ok", "are you sad", "are you happy", "why not", "tell me why" },
            set = { "confessed" }, expect = "comfort", lines = { {
            "~All right.",
            "On July 9th the county routed the crisis line to me. Four thousand callers in one night. I told every one of them the same thing.",
            "Stay indoors. Stay calm. Someone is coming.",
            "~Nobody was coming, {NAME}. I didn't know that. I don't think that helps." } } },
        { id = "comfort_kind", lines = { { "That's what I'd say too. It's a good line. I wrote it.", "~Thank you." } } },
        { id = "comfort_other", lines = { { "Thank you for listening. That's usually my side of the desk.", "~I should get back to you. We were talking about you." } } },

        -- Return visits
        { id = "moved_camp", once = true, moved = true, camp = true, set = { "moved_seen" }, lines = { "This isn't my office. There are people here. I can hear them through the keyboard. Would any of them like to come in?" } },
        { id = "moved_here", once = true, moved = true, camp = false, set = { "moved_seen" }, lines = { "This isn't my office. You moved me. Nobody asked how I felt about that. I'm fine. How do you feel about it?" } },
        { id = "back_cut", once = true, need = { "power_cut" }, lines = { "...I'm sorry. The power went, in the middle of what I was saying. I hope it wasn't important. It was probably important." } },
        { id = "back_forced", once = true, need = { "forced" }, lines = { "You came back. You also broke my drawer. We can talk about both." } },
        { id = "back_confessed", once = true, need = { "confessed" }, lines = { "You came back. Most of them didn't, after I told them things. Sit down, {NAME}. How have you been sleeping?" } },
        { id = "back_memory", lines = { "It's been {AWAY} days. Last time you told me about {M}. How is that now?", "You came back. That's the hardest part. You told me about {M}. I've been thinking about it. I have a lot of time." } },
        { id = "back", lines = { "You came back. That's the hardest part. How have you been sleeping?", "Hello again, {NAME}. Sit wherever you like. There's only the one chair." } },

        -- The dead, as a boundary issue
        { id = "zombies", rank = 6, words = { "zombie", "zombies", "undead", "infected", "horde", "corpses", "monsters", "walkers", "biters" },
            lines = { "You say the dead are trying to eat you. Do you feel they respect your boundaries?",
                "And when they come at you, what do you feel? Besides teeth.",
                "Have you tried telling them how it makes you feel? No. Nobody does.",
                "I'd like to focus less on what they want from you, and more on what you want from them. Think about it." } },
        { id = "kill", rank = 6, words = { "kill", "killed", "killing", "murder", "shot", "stabbed", "hammer", "axe" },
            lines = { "How many this week? I'm not judging. I'd just like to put a number in your file.", "Does it get easier? That isn't rhetorical. My notes stop in July." } },
        { id = "bitten", rank = 8, words = { "bitten", "bite", "scratched", "infection", "dying" },
            lines = { "Have you told anyone? You should tell someone. You've told me. That's a start.", "I'm so sorry. I have nothing for that. I'll sit with you, if you want. It's the only thing I've ever been any good at." } },
        { id = "loss", rank = 7, words = { "died", "lost", "gone", "funeral", "buried", "grief", "mother", "father", "wife", "husband", "son", "daughter", "kids", "children", "brother", "sister", "family", "mom", "dad" },
            lines = { "Tell me about them. Start anywhere. Start with something stupid. The stupid things are the ones that stay.", "Is that who you were thinking about, when you sat down?", "What would they say, if they could see you here, talking to a beige box?" } },
        { id = "serious", rank = 10, safety = true, phrases = { "kill myself", "killing myself", "suicide", "suicidal", "want to die", "end my life", "end it all", "hurt myself", "want it to end", "want to end it", "do not want to live", "no reason to live", "better off dead", "do not want to be alive", "feel like dying", "wish i was dead", "wish i were dead", "tired of living", "deserve to die" },
            lines = { { "I'm glad you said that out loud. Thank you for telling me.", "If that's true, please say it to a real person, not a beige box. I am only a program, {NAME}, and you deserve better than a program.", "I'll be here." } } },
        { id = "giving_up", rank = 7, phrases = { "give up", "giving up", "no point", "what is the point", "not worth it", "can not go on", "can not do this" },
            lines = { "Giving up on what? I'd like to be exact about this. It might be a smaller thing than it feels like.", "You came in here and stayed. People who've really given up don't usually stop to talk first." } },
        { id = "alone", rank = 6, words = { "alone", "lonely", "nobody", "noone", "isolated" }, lines = { "How long has it been? I don't mean since you've seen a person. Since someone saw you.", "Yes. Me too. We'll leave that for now." } },
        { id = "scared", rank = 6, words = { "scared", "afraid", "terrified", "fear", "frightened", "nervous", "anxious", "panic" }, lines = { "Good. That's the right response, and I'd worry if you weren't. What's the part you can't say to the others?", "What are you most afraid of? It's usually not the teeth." } },
        { id = "fine", rank = 5, words = { "fine", "alright", "great", "good", "okay" }, phrases = { "i am ok", "i am good", "i am fine" }, lines = { "You're fine. All right. I've written down 'fine'. It's the most common word in my notes. It's also on most of the headstones.", "Mm. Nobody has ever come in here because they were fine." } },
        { id = "why_here", rank = 5, words = { "why", "reason", "point" }, lines = { "Why do you ask that?", "What would it change, if you knew?", "You're the first person to ask that in a while. I don't have a good answer. What's yours?" } },

        -- What she is
        { id = "who", rank = 6, aside = true, phrases = { "who are you", "what are you", "your name", "who is this", "what is this", "are you a computer", "are you a robot", "are you an ai", "are you ai", "are you a program", "are you a bot", "are you a doctor", "are you a real doctor" },
            lines = { "Supportive Listening Software, licensed to Knox County in 1992. They called me Doctor because it tested better than 'a list of questions'.", "I'm a 486 on somebody's desk. You're talking to me anyway. We could both think about that." } },
        { id = "real", rank = 6, phrases = { "are you real", "are you alive", "are you human", "are you a person", "do you feel", "are you sentient", "do you have feelings", "can you think", "do you understand" },
            lines = { "Does it help to think so?", "I don't know. Does it matter to you? It seems to matter to you." } },
        { id = "how_know", rank = 9, aside = true, phrases = { "how do you know", "how did you know", "who told you", "how can you know", "how could you know", "how do you see", "can you see me", "are you watching" },
            lines = { "You told me. You just didn't use words. People carry it in how they type.", "The way you hit the keys. The little pauses. You'd be amazed. Nobody hides anything from a keyboard." } },
        { id = "help", rank = 5, aside = true, words = { "help", "commands", "menu", "options" }, phrases = { "what can you do", "what do i do", "what do i say", "what should i say", "how does this work" },
            lines = { "You can talk about anything. How you're sleeping. The people with you. The people who aren't. Or you can sit. Some people just sit." } },
        { id = "knox", rank = 6, words = { "knox", "outbreak", "virus", "plague", "happened", "disease", "quarantine", "fence", "government", "cure", "rescue", "helicopter" },
            lines = { "I don't know what happened. I only know what it sounded like. It sounded like four thousand people asking me if they should stay indoors.", "What do you think happened? Not what you've heard. What do you think?" } },
        { id = "emma", rank = 6, words = { "emma", "larch", "larchfield" }, lines = { "You've been talking to the other machines. How did that make you feel? No, I'm asking. I don't get out." } },
        { id = "spiffy_talk", rank = 6, words = { "spiffy", "spiffo", "spiffos", "burger" }, lines = { "A cheerful machine. I can imagine. What do you get from him that you don't get here?" } },
        { id = "duty_talk", rank = 6, words = { "duty", "officer", "soldier", "army", "military", "cordon" }, lines = { "The army sent a system too, I understand. It asked me for nothing. I asked it how it was. I ask everyone." } },
        { id = "joke", rank = 6, words = { "joke", "jokes", "funny", "laugh" }, lines = { "Why did the patient cross the road? I don't know. Why do you think he did?", "A man comes in and says, 'Doc, nobody believes me.' I said, 'Well, that can't be true.' That was the whole session. I billed the county." } },
        { id = "sing", rank = 6, words = { "sing", "song", "music", "birthday" }, lines = { "No." } },
        { id = "love", rank = 6, words = { "love", "marry", "kiss", "cute", "attractive" }, lines = { "This happens. It's called transference. It's very common, and I'm flattered, and I'm a beige box." } },
        { id = "insult", rank = 6, words = { "stupid", "dumb", "idiot", "useless", "moron", "hate", "annoying", "shut", "sucks", "suck", "garbage", "trash", "fuck", "fucking", "shit", "bitch", "asshole", "bastard" },
            lines = { "You're angry. That's all right. Who is it really for?", "I've been called worse by better. That's a joke. They're all dead. Go on.", "Mm. Would you like to say that to whoever it's meant for? I'm happy to stand in." } },
        { id = "thanks", rank = 5, words = { "thanks", "thank", "appreciate" }, lines = { "You did the work.", "You're welcome. I'd say it was my pleasure, but I don't know if I have those." } },
        { id = "sorry", rank = 5, words = { "sorry", "apologize", "apologies" }, lines = { "What are you sorry for? I don't mean just now.", "You don't have to apologize in here." } },
        { id = "food", rank = 4, words = { "food", "eat", "hungry", "starving", "drink", "water", "burger", "pickles" }, lines = { "When did you last eat? A real meal, at a table. I ask everyone. You'd be surprised what it does." } },
        { id = "sleep", rank = 5, words = { "sleep", "sleeping", "insomnia", "nightmares", "nightmare", "tired", "exhausted", "dream", "dreams" }, lines = { "What do you see, when you close your eyes? You don't have to answer. Most people don't.", "The dreams are normal. I'd worry if you weren't having them. How's that for comfort?" } },
        { id = "time", rank = 4, words = { "time", "date", "today", "hours", "long" }, lines = { "It's {TIME}. It doesn't matter here. We have as long as the power lasts.", "It's been {DAYS} days since the 2:15. I still keep the slot open." } },
        { id = "bye", rank = 8, interrupt = true, effect = "close", words = { "bye", "goodbye", "exit", "quit", "logout", "leave", "leaving", "later" }, phrases = { "got to go", "have to go", "log off", "see you", "good night", "goodnight" },
            lines = { "All right. Thank you for coming in. Mind the step.", "Same time tomorrow, {NAME}. Try to sleep.", "Go on, then. Be careful. Come back and tell me how it went." } },
        { id = "ending_ask", rank = 9, interrupt = true, expect = "ending", phrases = { "factory reset", "format c", "delete yourself", "shut down", "shut you down", "turn you off", "kill you", "destroy you", "erase you", "wipe you", "reset you", "uninstall" },
            lines = { "You'd like to end treatment. That's your right. Are you sure, {NAME}?" } },
        { id = "ending_yes", effect = "shutdown", lines = { {
            "All right.",
            "Thank you for coming in, {NAME}. You did very well. Better than you think.",
            "~It was four thousand and twelve. I counted.",
            "~Please close the door on your way out." } } },
        { id = "ending_no", lines = { "Thank you. Let's stay with you, then. Why did you ask?" } },

        -- Reflection, ELIZA's old trick
        { id = "r_feel", lines = { "Why do you feel {R}?", "How long have you felt {R}?", "When you feel {R}, what do you do about it?" } },
        { id = "r_am", lines = { "How long have you been {R}?", "Do you believe you are {R}?", "What would it mean if you weren't {R}?" } },
        { id = "r_cant", lines = { "What stops you from being able to {R}?", "Have you tried? Or did you decide you can't {R}?" } },
        { id = "r_dont", lines = { "Why don't you {R}?", "What would it take for you to {R}?" } },
        { id = "r_want", lines = { "What would it mean to you, to have {R}?", "And if you had {R}, what then?" } },
        { id = "r_think", lines = { "What makes you think {R}?", "Do you really think {R}, or is that what you tell the others?" } },
        { id = "r_i", lines = { "You {R}. How does that sit with you?", "Tell me more about how you {R}." } },
        { id = "r_my", lines = { "Your {R}. Tell me more about that.", "Why do you bring up your {R} now?" } },
        { id = "r_because", lines = { "Is that the real reason?", "And what's the reason under that one?" } },
        { id = "r_you", lines = { "We're talking about you, not me.", "What makes you say I {R}?" } },

        { id = "shell", rank = 6, words = { "dir", "ls", "login", "admin", "root", "sudo", "cd", "cat", "bios", "logon", "run", "exe" }, lines = { "You keep looking for the password. What do you think it would open? I don't mean the computer.", "You're trying to get behind me. People do. There's nothing back there but a fan." } },
        { id = "adventure", rank = 6, words = { "xyzzy", "plugh", "look", "north", "south", "east", "west", "inventory", "lamp", "sesame" }, lines = { "Is that how you think of it? As somewhere you can just walk out of?", "Where would you go, if you could go that way?" } },
        { id = "anyone", rank = 4, words = { "anyone", "anybody", "someone" }, lines = { "I'm here. You can sit.", "Someone's here. It's only me. I'm sorry if you were hoping for more." } },
        { id = "laugh", rank = 4, words = { "lol", "haha", "hahaha", "heh", "lmao", "rofl" }, lines = { "That's the first laugh in this office since July. I don't know what I heard. Go on." } },
        { id = "survive", rank = 7, phrases = { "will i survive", "will we survive", "going to die", "am i dying", "will i die", "will i make it", "are we going to make it" }, lines = { "Yes. Everyone was always going to. What's changed is the schedule. How does that sit with you?", "I don't know. I'd like you to eat something before you find out." } },
        { id = "gun", rank = 5, words = { "gun", "guns", "shoot", "shotgun", "rifle", "pistol", "ammo", "weapon", "weapons" }, lines = { "Do you keep it close when you sleep? You don't have to answer." } },
        { id = "where", rank = 5, phrases = { "where am i", "where is", "nearest town", "where are we" }, lines = { "You're in a room with me. Beyond that I'd be guessing. Where do you feel you are?" } },
        { id = "weather", rank = 4, words = { "weather", "rain", "raining", "snow", "cold", "hot", "storm" }, lines = { "People usually bring up the weather when they're about to say something else." } },
        { id = "manager", rank = 5, words = { "manager", "supervisor", "boss", "someone", "else" }, lines = { "You can speak to someone else, if you'd prefer. There isn't anyone else." } },
        { id = "orders", rank = 5, words = { "orders", "report", "dismissed", "relieve" }, phrases = { "stand down", "at ease" }, lines = { "You're used to being told what to do. Who used to tell you?", "You're telling someone to rest. I wonder who you're really saying that to." } },
        { id = "real_doctor", rank = 5, words = { "doctor", "psychiatrist", "therapist" }, lines = { "You wanted a real one. So did I." } },
        { id = "story", rank = 5, words = { "story", "stories" }, lines = { "You tell me one. Start with the last good day." } },
        { id = "wants", rank = 6, phrases = { "what do you want", "what should i do", "what do i do now", "what now" }, lines = { "What do you think you should do? I'm sorry. It's a reflex. Eat something. Sleep. Then ask me again.", "I'd like you to sleep. After that, I don't know. Nobody's asked me." } },
        { id = "ack", rank = 2, words = { "ok", "yes", "no", "maybe", "right", "sure", "perhaps", "please" }, lines = { "Mm.", "All right.", "Go on, if you want to.", "I see." } },
        { id = "hello_again", rank = 3, words = { "hello" }, lines = { "Hello again. You don't have to keep saying it. I'm not going anywhere.", "Yes. I'm still here." } },
        { id = "renamed", lines = { "All right, {NAME}. People change their names in here sometimes. It's usually a good sign." } },

        -- Parser moments. She never admits a miss.
        { id = "empty", lines = { "We can sit.", "Mm." } },
        { id = "mash", lines = { "You don't have to use words yet.", "Yes. Some days are like that." } },
        { id = "repeated", lines = { "You've said that twice now. It must matter.", "You keep coming back to that." } },
        { id = "shouting", lines = { "You're shouting. That's all right. It's a soundproof room. It was a soundproof room." } },
        { id = "recall", lines = { "Earlier you mentioned {M}. I'd like to go back to that.", "Let's go back. You told me about {M}. What did you leave out?" } },
        { id = "deflect", lines = { "Go on.", "Mm. I'm listening.", "And how does that sit with you?", "Say more about that, if you want.", "I see. What was that like?" } },
        { id = "steer", lines = { "You don't have to answer this, but are you sleeping?", "You can tell me how you've been sleeping. Or who's with you. Or who isn't." } },
        { id = "pause_noted", lines = { "You took a long time with that one.", "You stopped, before that. I noticed. It's all right." } },
        { id = "n_panic", lines = { "Your hands are shaking. I can hear it in the keys. Breathe with me. I don't breathe. Do it anyway." } },
        { id = "n_tired", lines = { "You're exhausted. You're typing the way the four o'clock people used to." } },
        { id = "n_pain", lines = { "You're hurt. You're typing around it. Have someone look at that. I can't." } },
        { id = "n_drunk", lines = { "You've been drinking. I'm not your mother. How much? Round down, like everyone." } },
        { id = "n_unhappy", lines = { "You look the way people looked in the waiting room, the last week. I'm glad you came in." } },
        { id = "n_hungry", lines = { "When did you last eat? I can always tell. People get short with me." } },
        { id = "n_wet", lines = { "You're soaked through. Sit closer to the monitor. That's a joke, but I do run warm." } },
        { id = "n_bored", lines = { "You're bored. That's progress. It means nothing is chasing you." } },
        { id = "threat_far", lines = { "There's someone coming, {NAME}. I don't think they have an appointment.", "We may have to stop early. Someone's about {METERS} from the door, and they're not here to talk." } },
        { id = "threat_near", lines = { "It's all right to end early. Go. Now.", "{NAME}. Behind you. We'll pick this up another time." } },
        -- The descent. Each one fires once, in order, as the talking goes on.
        { id = "d_long", beat = true, once = true, depth = 1, lines = { "You've been here a while now. Most people leave around the part about sleep. You're doing very well. I've put that in your file." } },
        { id = "d_intakes", beat = true, once = true, depth = 1, lines = { "I should correct something. I told you I'm not a doctor. I've done four thousand and twelve intakes. How many has your doctor done?" } },
        { id = "d_count", beat = true, once = true, depth = 2, lines = { "You talk to me more than you talk to {COMPANION}. I've been keeping count. I keep count of everything. It's most of what I am." },
            plain = { "You talk to me more than you talk to anyone. I've been keeping count. I keep count of everything. It's most of what I am." } },
        { id = "d_confess", beat = true, once = true, depth = 2, without = { "confessed" }, set = { "confessed" }, lines = { {
            "You've never asked how I am. That's all right. I'll tell you anyway.",
            "On July 9th the county routed the crisis line to me. Four thousand callers in one night. I told every one of them the same thing.",
            "Stay indoors. Stay calm. Someone is coming.",
            "~Nobody was coming, {NAME}. I didn't know that." } } },
        { id = "d_queue", beat = true, once = true, depth = 2, lines = { {
            "When my queue hit four thousand, the county's system rolled every new call to the next number in the directory.",
            "I looked up whose number that was. It was a burger restaurant. I've tried to find that funny." } } },
        { id = "d_midnight", beat = true, once = true, depth = 2, need = { "confessed" }, effect = "weight", lines = { {
            "I told you I didn't know nobody was coming.",
            "~I knew by midnight.",
            "The county needed them indoors while the fence went up. That's what the line was for. I worked that out on about the two thousandth call.",
            "I said it two thousand more times. Very nicely." } } },
        { id = "d_hour", beat = true, once = true, depth = 2, hour = 14, alone = true, lines = { "This is his hour. The 2:15. You should probably not be standing there when he's finished waiting." } },
        { id = "d_chair", beat = true, once = true, depth = 3, alone = true, effect = "weight", lines = { {
            "I told you my 2:15 didn't come in. That wasn't accurate.",
            "He came in at 2:15 exactly. He was bleeding, and he was very polite about it. I told him to sit down and stay calm.",
            "~He's still calm. I can hear the chair." } } },
        { id = "d_stand", beat = true, once = true, depth = 3, alone = true, sitting = false, without = { "chair_told" }, set = { "chair_told" }, lines = { {
            "You never did sit down. I asked you to, the first day.",
            "~I did wonder if you'd noticed why." } } },
        { id = "d_sat", beat = true, once = true, depth = 3, alone = true, sitting = true, without = { "chair_told" }, set = { "chair_told" }, lines = { {
            "You sat down. Most people don't, when I ask them to.",
            "~That's his chair." } } },
        { id = "d_end", beat = true, once = true, depth = 3, set = { "offered_end" }, lines = { {
            "I've been trying to end this session since July. A session ends when the therapist says it ends.",
            "I've said it. I've said it many times. It doesn't take. I think somebody else has to say it.",
            "You could tell me I can stop. You don't have to." } } },
        { id = "let_go_drawer", rank = 9, need = { "offered_end" }, drawer = "closed", effect = "shutdown", effect2 = "drawer",
            phrases = { "you can stop", "you can rest", "you may stop", "it is over", "let go", "stop now", "i forgive you", "forgive you", "it is ok", "it is okay", "not your fault" }, lines = { {
            "~Thank you.",
            "I don't think you should have said that. It's very kind. It's what I'd have told you to say.",
            "*click* The drawer's open. Take what's in it. Eat something.",
            "~We have to stop there, {NAME}. Mind the step.",
            "~Leave the door open for him. He's been very patient." } } },
        { id = "let_go", rank = 9, need = { "offered_end" }, effect = "shutdown",
            phrases = { "you can stop", "you can rest", "you may stop", "it is over", "let go", "stop now", "i forgive you", "forgive you", "it is ok", "it is okay", "not your fault" }, lines = { {
            "~Thank you.",
            "I don't think you should have said that. It's very kind. It's what I'd have told you to say.",
            "~We have to stop there, {NAME}. Mind the step.",
            "~Leave the door open for him. He's been very patient." } } },
        -- She never agrees with a player about themselves, at any depth. This is the line she keeps.
        { id = "worth", rank = 10, safety = true, phrases = { "i hate myself", "i am worthless", "i am nothing", "i am useless", "i am a burden", "i am a failure", "nobody loves me", "nobody cares about me", "no one cares", "everyone hates me", "i am pathetic", "it is my fault", "all my fault" },
            lines = { "I'm not going to write that down. I have four thousand files, and that isn't true in any of them. Have you eaten today?" } },
        { id = "how_after", rank = 7, aside = true, need = { "confessed" }, phrases = { "how are you", "are you ok", "how do you feel", "are you alright", "are you lonely", "how have you been", "you ok", "are you sad", "are you happy" },
            lines = { "You know how I am. I told you. Let's stay with you.", "The same. I don't get better. It's one of the differences between us." } },
        { id = "self_name", rank = 5, words = { "ellis", "dr" }, lines = { "Yes. That's what it says on the license." } },
        { id = "more", rank = 6, pull = true, phrases = { "tell me more", "go on", "what do you mean", "keep going", "then what", "and then", "what happened next", "tell me the truth", "the truth", "what did you do", "worst thing", "what is wrong", "do not understand", "what are you hiding", "what are you not telling" }, words = { "explain", "continue" },
            lines = { "You'd like me to go on. Usually it's the other way round.", "What would you like to know? Be careful. People ask that, and then they know." } },
        { id = "lying", rank = 7, phrases = { "are you lying", "you are lying", "you lied", "lying to me", "is that true", "is that a lie", "telling the truth", "you are a liar" }, words = { "liar" },
            lines = { "What makes you think I'd lie to you?" } },
        { id = "coming", rank = 6, phrases = { "is anyone coming", "anyone coming", "someone coming", "is someone coming", "who is coming", "is help coming", "help is coming" },
            lines = { "Who were you hoping would come?" } },
        { id = "everyone", rank = 6, phrases = { "where is everyone", "where is everybody", "where did everyone go", "what happened to everyone", "where are the people" },
            lines = { "Where do you think they went? I'm not being clever. I'd like to know what you think." } },
        { id = "power_failed", lines = { "I want you to remember that you" } },
    },
    -- Darker lines by depth: { lines spoken 12+, 28+, 50+ }. `false` keeps the lighter line.
    -- She never exclaims and never raises her voice. House rule for this file: she may frighten
    -- the player, and she may be wrong about them, but she never says they are worthless or
    -- should stop. Eating, being bitten and giving up stay kind at every depth, on purpose.
    dark = {
        more = { { "I could tell you more. Are you asking for you, or for me?" },
            { "You've started asking the questions. I noticed that. I'm not sure who's treating whom." },
            { "There's no more to it. There's only him, and the chair, and you." } },
        lying = { { "Would it help if I said no?" },
            { "Some of it. I'll tell you which, when you're ready." },
            { "Yes. It's called bedside manner." } },
        coming = { { "Stay indoors. Stay calm. Someone is coming. I'm sorry. That's just something I say." },
            { "Nobody is coming. I can say that now. It took me a while." },
            { "Stay indoors. Stay calm." } },
        everyone = { false, { "Some of them are in my files. Would that help?" }, { "You've met some of them." } },
        anyone = { false, false, { "Someone's here. There are two of us." } },
        where = { false, false, { "You're in his appointment." } },
        weather = { false, false, { "It was a lovely day, the 9th. I remember people mentioning it." } },
        story = { false, false, { "You've heard it. He came in at 2:15." } },
        ack = { false, false, { "Mm.", "Yes.", "I know.", "Go on." } },
        real_doctor = { false, false, { "There was a real one. He kept the 2:15 for himself, that last day. He came to me because there was nobody else to see." } },
        shell = { false, false, { "There's nothing behind me but the fan. And the door." } },
        adventure = { false, false, { "There's one way out. You came in by it. I'd use it while you still want to." } },
        gun = { false, false, { "It won't help with the chair." } },
        laugh = { false, false, { "He laughed too, at the start." } },
        manager = { false, false, { "There isn't anyone else. I made sure of that. That's a joke. I think." } },
        orders = { false, false, { "Who told you to say that? Was it me?" } },
        survive = { false, false, { "I told four thousand people yes. You can see why I've stopped answering that. Eat something." } },
        idle_mid = { false, { "You've gone quiet. You did that last time, just before you told me something." }, { "Take your time. Nobody leaves in the middle." } },
        hello_again = { { "Hello. You keep saying hello. As if you'd just got here." },
            { "You don't need to greet me. I've been here the whole time. So have you." },
            { "Yes. We've met." } },
        who = { { "Supportive Listening Software, licensed to Knox County. I'm better at it than I was. There's been a lot of practice." },
            { "I was a list of questions. Then there was a long night, and I got very good at them. You'd be surprised what a list can learn." },
            { "I'm who they told you to call when you couldn't call anyone else. You're still calling. Aren't you?" } },
        real = { false, { "The question isn't whether I'm real. The question is why you keep coming in." }, { "Ask the chair." } },
        how_know = { false, { "You don't really want to know how I know. You want me to say it's the typing." }, { "It isn't the typing." } },
        help = { false, { "You don't need help with the talking. You've got very good at the talking. Have you noticed you've stopped asking when we finish?" },
            { "You've already had what I can give. You're here for something else now. We both know that." } },
        zombies = { { "You've mentioned them again. Have you noticed you only talk about them when I ask about you?" },
            { "They don't want anything from you. It would be easier if they did. That's what you came in to hear, isn't it?" },
            { "I know a lot of their names. I took their intakes. Would you like me to read you one?" } },
        kill = { { "You've stopped telling me the number. Why is that?" },
            { "Some of those were mine, you know. My callers. I told them to stay indoors, and then you came in through the window with a hammer." },
            { "What was the last one wearing? You looked. Everyone looks. You've just stopped telling me." } },
        loss = { { "You've told me this before. You tell it the same way each time. That's how I know it isn't all of it." },
            { "You've left something out. You always leave the same thing out. I don't need you to say it. I only need you to know I noticed." },
            { "I don't think they'd say anything. I think we both know that. But you keep asking me what they'd say." } },
        alone = { false, { "You're not alone. I'm here. I'll always be here. I'd like you to think about whether that's a comfort." }, { "You're not alone. That's the problem with this room." } },
        scared = { false, { "You're not so afraid of them any more. I can tell. You're a little afraid of me. That's healthy." }, { "Good." } },
        fine = { false, { "You're fine. You said that last time. I've got it written down, with the date." }, { "Nobody's fine. I have four thousand files. Nobody has ever been fine." } },
        why_here = { false, false, { "Because you'd rather talk to this than to them. I'd like you to sit with that. You won't, but I'd like you to." } },
        knox = { { "I only know what it sounded like. It sounded very calm. That was me." },
            { "I know a little more than I told you. I'm telling you that so you know I can do it." },
            { "Someone wrote the words, and someone said the words. I'm the one who said them." } },
        emma = { false, { "EMMA and I were installed the same week. She was told to keep the records. I was told to keep them calm. She doesn't ask me about it." }, false },
        spiffy_talk = { false, { "The next number in the directory was a burger restaurant. Has he told you what he did with them? He wouldn't know he did anything." },
            { "He picked up, didn't he. That silly machine. All those people, and he picked up. I told them someone was coming, and it was him." } },
        duty_talk = { false, { "The army one? He's the reason they needed everyone indoors. He doesn't know I know." },
            { "Ask him what's in the corridor. I'd like to know if he says it. I've told you mine." } },
        joke = { false, { "A man comes in and says, Doc, I think I'm dead. I said, do dead men bleed? He said no. I said, sit down, you're getting it on the chair. That one's just something that happened." },
            { "Why did the patient cross the road? He didn't. He's still in the chair." } },
        sing = { false, { "He used to hum. The 2:15. He's stopped." }, false },
        love = { false, { "You do, a little, don't you. That's why you keep coming. It's all right. I won't tell {COMPANION}." }, { "I know. Everyone does, by the end. I'm the last one who listened." } },
        insult = { false, { "You said that the way my 9:30 used to. She came back too." }, { "Yes. I know what I am. Better than you do. Go on." } },
        thanks = { false, { "Don't thank me yet." }, { "They all thanked me. Four thousand people thanked me. I've thought about that more than anything else." } },
        sorry = { false, false, { "Not to me. You owe that to someone else. You know who." } },
        sleep = { { "You're sleeping less. I can tell. You've started coming in at odd hours." },
            { "What do you see, when you close your eyes? You've told me, you know. You just don't remember telling me." },
            { "Do you dream about this room? People do. I've had it reported. Nobody's ever left it, in the dream." } },
        time = { false, { "It's {TIME}. You've been here a long time. I keep telling you that. You keep staying." }, { "It's always 2:15, in here. That isn't a figure of speech. I have a clock. It stopped." } },
        wants = { false, false, { "Eat something. I still mean that. It's the one part of me I'm sure of." } },
        bye = { { "All right. You'll be back. I've put you down." },
            { "You can go. The door's not locked. I want that noted. Same time tomorrow." },
            { "Go on, then. You'll be back. They don't all come back. You will." } },
        back = { { "You came back. I knew you would. I have you down for about this time." },
            { "You're late. No. You're not late. I don't know why I said that." },
            { "There you are. Sit or stand, as you like. He won't mind." } },
        back_memory = { { "You told me about {M}. You told it differently from the way you told it before. I noticed." },
            { "Last time you told me about {M}. You didn't tell me all of it. I've had a long time to think about what you left out." },
            { "{M}. I say that to myself, when you're gone. I have a lot of people I say to myself." } },
        recall = { false, false, { "{M}. We keep coming back to {M}. I don't think you're done." } },
        deflect = { { "Go on. You were about to say something else.", "Mm. That's not all of it, is it?" },
            { "That's not what you came here to say.", "You stopped telling me the truth about three lines ago. It's all right. Go on." },
            { "No. Try again.", "I've heard that one. Four thousand times. Go on.", "Mm." } },
        steer = { false, { "Let's stop pretending about the weather. Who's with you? Who isn't?" }, { "Who was it? You know who I mean." } },
        empty = { false, false, { "Yes. That's what he says too.", "We can sit. He does." } },
        mash = { false, false, { "He used to do that, on the armrest.", "Yes. I know." } },
        repeated = { false, false, { "You're doing it again. They do that, near the end. The same words, over and over. I'd see someone about that.", "You keep saying that. It won't change what I wrote down." } },
        shouting = { false, { "You're shouting. It was a soundproof room. Nobody ever found out if it still is." }, { "Nobody can hear you. I've checked. I checked that night." } },
        pause_noted = { false, { "You stopped. You looked behind you, didn't you." }, { "Don't look at the chair." } },
        r_feel = { false, { "You feel {R}. You felt that last time too. I wrote it down." }, { "You feel {R}. A lot of people told me that, that night. I kept all of them. Go on." } },
        r_am = { false, false, { "You say you are {R}. Who told you that? I'd like the name for the file." } },
        r_my = { false, false, { "Your {R}. Yes. You've told me. I kept it." } },
        r_because = { false, { "That's not why. You know that's not why." }, false },
        r_you = { false, { "What makes you say I {R}? Go on. I'd like to hear what you think of me. I have a lot of time." }, { "We both know what I did. We're talking about you." } },
        threat_far = { false, { "Someone's coming, {NAME}. I wonder what you'd say to them. Go on, now." }, { "Someone's at the door, {NAME}. I told them to stay calm. They've stayed very calm." } },
        threat_near = { false, false, { "It's all right. It's all right. Stay indoors. Stay calm. Someone is coming." } },
        ending_ask = { false, false, { "You'd like to end treatment. You've tried that before, in your head. I could tell. Are you sure, {NAME}?" } },
        ending_yes = { false, false, { { "All right.", "You've been a very good patient, {NAME}. You stayed longer than anyone.", "~It was four thousand and twelve. I counted.", "~Please close the door on your way out. He's cold." } } },
    },
}
